import { Router, Request, Response } from 'express';
import { z } from 'zod';

const querySchema = z.object({ page: z.coerce.number().int().min(1).default(1) });
const bodySchema = z.object({ name: z.string().min(1) });

const router = Router();
router.post('/{{resource}}', (req: Request, res: Response) => {
  const q = querySchema.safeParse(req.query);
  const b = bodySchema.safeParse(req.body);
  if (!q.success || !b.success) {
    return res.status(400).json({ errors: { query: q.error?.issues, body: b.error?.issues } });
  }
  res.json({ page: q.data.page, name: b.data.name });
});

export default router;
